LowerBound:
var lo := 0;
var hi := |s|;
while lo < hi
    invariant 0 <= lo <= hi <= |s|
    invariant forall i: int :: 0 <= i < lo ==> s[i] < key
    invariant forall i: int :: hi <= i < |s| ==> s[i] >= key
    decreases hi - lo
{
    var mid := lo + (hi - lo) / 2;
    if s[mid] < key {
        lo := mid + 1;
    } else {
        hi := mid;
    }
}
p := lo;
assert forall i: int :: 0 <= i < p ==> s[i] < key;
assert forall i: int :: p <= i < |s| ==> s[i] >= key;
return p;
